<?php

namespace App\Http\Controllers\Cdv;

use App\Http\Controllers\Controller;
use Illuminate\Http\Request;
use App\Models\{User, Notes, Regions};


class DashboardController extends Controller
{
    protected function getUserRegion($services)
    {
        $regions = Regions::find($services->pluck('region'));
        return json_decode($regions, true);
    }

    
    protected function getConnectedUserData(User $user): ?User
    {
        $userData = User::where('matricule', $user->matricule)
            ->with(['service', 'notes' => fn($q) => $q->latest()->limit(1)])
            ->first();

        if ($userData) {
            $userData->evaluation_count = $userData->notes()->count();
            $userData->latest_evaluation = $userData->notes->first();
            $userData->has_score = $userData->notes->isNotEmpty();
            unset($userData->notes);
        }

        return $userData;
    }

    protected function getColleagues($serviceIds,User $user)
    {
        return User::where('parent_id',$user->matricule)
            ->whereHas('service', fn($q) => $q->whereIn('services_cciaux.id', $serviceIds))
            ->Where(function ($query) {
                $query->whereHas('service', fn($q) => $q->where('type', 'CDS'));
            })
            ->with(['service', 'notes' => fn($q) => $q->latest()->limit(1)])
            ->get()
            ->map(function ($user) {
                $user->evaluation_count = $user->notes()->count();
                $user->latest_evaluation = $user->notes->first();
                $user->has_score = $user->notes->isNotEmpty();
                unset($user->notes);
                return $user;
            });
    }

    public function dashboard(){
        $currentUser = auth()->user();

        if ($currentUser->type !== 'CDV') {
            return response()->json(['message' => 'Only CDV users can access this resource'], 403);
        }

        $services = $currentUser->service;
        if ($services->isEmpty()) {
            return response()->json(['message' => 'No services found for this user'], 404);
        }

        $serviceIds = $services->pluck('id');
        
        $connectedUserData = $this->getConnectedUserData($currentUser);
        $colleagues = $this->getColleagues($serviceIds,$currentUser);
        $region = $this->getUserRegion($services);
        $cdv = $connectedUserData ;

        session(['user_region' => $region[0]['nom'] ?? null]);

        return view('cdv.dashboard', compact('colleagues', 'cdv', 'region'));
    }

    public function index()
    {
        $currentUser = auth()->user();
        // $user = User::with('service')->findOrFail($userId);
        $evaluations = Notes::with(['user', 'creator'])
            ->where('id_utilisateur', $currentUser->matricule)
            ->get();
        $services = $currentUser->service;
        $region = $this->getUserRegion($services);
        session(['user_region' => $region[0]['nom'] ?? null]);
        return view('cdv.index', compact('currentUser','evaluations'));
    }

    public function indexCDS($userId)
    {
        $user = User::with('service')->findOrFail($userId);
        $evaluations = Notes::with(['user', 'creator'])
            ->where('id_utilisateur', $userId)
            ->get();
        $services = $user->service;
        $regions = $this->getUserRegion($services);
        $region = $regions[0]['nom']; 
        return view('cdv.cds.index', compact('user','region' ,'evaluations'));
    }

    public function create(){
       
